#include <vector>
#include <cstddef>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    const std::size_t n = x.size();
    unsigned int parity = 0u;

    #pragma omp parallel for default(none) shared(x, n) reduction(^ : parity)
    for (std::size_t i = 0; i < n; ++i) {
        parity ^= static_cast<unsigned int>(x[i]);
    }

    return parity != 0u;
}
